import React from 'react';
import {AbsoluteFill} from 'remotion';
import {useS, en, idx, T, DUR, Camara, Textura, Profundidad, Brillo, Paso, tono, Chip, Contador, Ondas, Impacto, Recorrido, enCamino, seguir, golpe, interpolate, clamp, h, FONT, Easing} from './kit';

// ---------- utilidades ----------
const cl = (v: number, a = 0, b = 1) => Math.max(a, Math.min(b, v));
const eo = (x: number) => 1 - Math.pow(1 - cl(x), 3);
const eio = (x: number) => { const k = cl(x); return k < 0.5 ? 4 * k * k * k : 1 - Math.pow(-2 * k + 2, 3) / 2; };
const ro = (s: number, a: number, b: number) => cl((s - a) / (b - a));
const P = (t: number, x: number, y: number, z: number) => ({t, x: cl(x, 540 / z, 1080 - 540 / z), y: cl(y, 1000 / z, 1920 - 920 / z), zoom: z});
const scr = (c: {x: number; y: number; zoom: number}, x: number, y: number) => ({x: 540 + (x - c.x) * c.zoom, y: 1000 + (y - c.y) * c.zoom});
const GOLD = '#FFC83D';
const RED = '#FF4D4D';
const GREEN = '#50DC8C';
const BLUE = '#5B8CFF';
const PIELES = [['#f3d2b0', '#e3b88e', '#c99a6e'], ['#e0a878', '#c98f5e', '#9c6a40'], ['#b57b52', '#8a5a36', '#5e3a22'], ['#7a4f2c', '#5e3a22', '#3d2414'], ['#fffaf0', '#ece2c8', '#c4b68e']];
// SFX: nunca dos a menos de 0,27 s aunque la voz real cambie los tiempos
const fix = (l: {t: number; s: string}[]) => {
  const o: {t: number; s: string}[] = [];
  let last = -9;
  [...l].sort((a, b) => a.t - b.t).forEach((e) => { if (e.t - last >= 0.27) { o.push(e); last = e.t; } });
  return o;
};
const sf = (p: string, s: string, o = 0, n = 1) => ({t: en(p, n) + o, s});
// posicion que viaja por puntos de paso {t,x,y} con suavizado
const wp = (s: number, pts: {t: number; x: number; y: number}[]) => {
  const ts = pts.map((p) => p.t);
  const o = {...clamp, easing: Easing.inOut(Easing.cubic)};
  return {x: interpolate(s, ts, pts.map((p) => p.x), o), y: interpolate(s, ts, pts.map((p) => p.y), o)};
};

// ---------- piezas dibujadas ----------
const Polvo: React.FC<{n?: number; color?: string}> = ({n = 24, color = 'rgba(255,255,255,0.55)'}) => {
  const {s} = useS();
  return (
    <svg width={1080} height={1920} style={{position: 'absolute', inset: 0}}>
      {Array.from({length: n}).map((_, i) => {
        const x = h(i * 3 + 1) * 1080 + Math.sin(s * 0.6 + i) * 30;
        const y = (((h(i * 7 + 2) * 1920 - s * (12 + h(i) * 22)) % 1920) + 1920) % 1920;
        return <circle key={i} cx={x} cy={y} r={2 + h(i * 5) * 4} fill={color} opacity={0.2 + h(i * 11) * 0.35} />;
      })}
    </svg>
  );
};

// mano con indice opcional; manga = color de la manga; largo = manga extra hacia abajo
const Mano: React.FC<{x: number; y: number; r?: number; k?: number; dedo?: boolean; piel?: number; manga?: string; largo?: number}> = ({x, y, r = 0, k = 1, dedo = true, piel = 1, manga, largo = 0}) => {
  const C = PIELES[piel];
  const F = `url(#pm${piel})`;
  const L = C[2];
  return (
    <g transform={`translate(${x} ${y}) rotate(${r}) scale(${k})`}>
      <defs><linearGradient id={`pm${piel}`} x1="0" y1="0" x2="1" y2="0"><stop offset="0%" stopColor={C[0]} /><stop offset="55%" stopColor={C[1]} /><stop offset="100%" stopColor={C[2]} /></linearGradient></defs>
      <rect x={-64} y={80} width={128} height={420} rx={50} fill={F} stroke={L} strokeWidth={4} />
      <rect x={-80} y={-70} width={160} height={190} rx={56} fill={F} stroke={L} strokeWidth={4} />
      {[[-58, 70], [-20, 55], [20, 60], [58, 75]].map(([fx, fl], i) => (
        <rect key={i} x={fx - 17} y={-70 - (i === 1 && dedo ? 150 : fl)} width={34} height={(i === 1 && dedo ? 150 : fl) + 40} rx={17} fill={F} stroke={L} strokeWidth={3} />
      ))}
      <rect x={-128} y={-20} width={34} height={110} rx={17} fill={F} stroke={L} strokeWidth={3} transform="rotate(-38 -110 60)" />
      <path d="M -80 -20 Q -30 -50 20 -20" stroke="rgba(255,255,255,0.28)" strokeWidth={6} fill="none" strokeLinecap="round" />
      {manga && (
        <g>
          <rect x={-76} y={118} width={152} height={420 + largo} rx={16} fill={manga} stroke="rgba(0,0,0,0.4)" strokeWidth={3} />
          <rect x={-80} y={104} width={160} height={34} rx={9} fill="#f4f0e6" stroke="#bdb7a4" strokeWidth={3} />
        </g>
      )}
    </g>
  );
};

const Moneda: React.FC<{x: number; y: number; k?: number; r?: number}> = ({x, y, k = 1, r = 0}) => (
  <g transform={`translate(${x} ${y}) rotate(${r}) scale(${k})`}>
    <ellipse cy={44} rx={30} ry={8} fill="rgba(0,0,0,0.25)" />
    <circle r={38} fill="#e8a516" stroke="#7a5a10" strokeWidth={4} />
    <circle r={29} fill="#ffd45a" stroke="#c98d10" strokeWidth={3} />
    <text y={13} textAnchor="middle" fontFamily={FONT} fontWeight={800} fontSize={38} fill="#8a5d08">$</text>
    <path d="M -24 -12 Q -10 -30 8 -26" stroke="rgba(255,255,255,0.7)" strokeWidth={5} fill="none" strokeLinecap="round" />
  </g>
);

const Billete: React.FC<{x: number; y: number; r?: number; k?: number; c?: string}> = ({x, y, r = 0, k = 1, c = '#58b068'}) => (
  <g transform={`translate(${x} ${y}) rotate(${r}) scale(${k})`}>
    <rect x={-86} y={-44} width={180} height={100} rx={8} fill="rgba(0,0,0,0.25)" />
    <rect x={-90} y={-50} width={180} height={100} rx={8} fill={c} stroke="rgba(0,0,0,0.4)" strokeWidth={4} />
    <rect x={-76} y={-38} width={152} height={76} rx={4} fill="none" stroke="rgba(255,255,255,0.5)" strokeWidth={3} />
    <circle r={26} fill="rgba(255,255,255,0.3)" />
    <text y={14} textAnchor="middle" fontFamily={FONT} fontWeight={800} fontSize={40} fill="rgba(0,0,0,0.5)">$</text>
    <path d="M -70 -30 Q -40 -44 -10 -38" stroke="rgba(255,255,255,0.6)" strokeWidth={5} fill="none" strokeLinecap="round" />
  </g>
);

// LED rojo con halo y punto blanco
const Led: React.FC<{x: number; y: number; r?: number; a?: number; c?: string; ph?: number}> = ({x, y, r = 14, a = 1, c = RED, ph = 0}) => {
  const {s} = useS();
  const p = 0.78 + 0.22 * Math.sin(s * 3.2 + ph);
  if (a <= 0.01) return null;
  return (
    <g opacity={a}>
      <circle cx={x} cy={y} r={r * 5.5 * p} fill={c} opacity={0.1} />
      <circle cx={x} cy={y} r={r * 3 * p} fill={c} opacity={0.22} />
      <circle cx={x} cy={y} r={r * 1.7} fill={c} opacity={0.5} />
      <circle cx={x} cy={y} r={r} fill="#ff8a8a" stroke={c} strokeWidth={2} />
      <circle cx={x - r * 0.3} cy={y - r * 0.3} r={r * 0.35} fill="#fff" opacity={0.9} />
    </g>
  );
};

// cartera de cuero; abre 0..1 (la solapa baja), lleno 0..1 (billetes que asoman)
const CarteraAb: React.FC<{x: number; y: number; k?: number; abre: number; lleno: number; c1?: string; c2?: string}> = ({x, y, k = 1, abre, lleno, c1 = '#58b068', c2 = '#6fc27a'}) => {
  const n = Math.round(lleno * 5);
  return (
    <g transform={`translate(${x} ${y}) scale(${k})`}>
      <defs><linearGradient id="cueroW" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#8a5a34" /><stop offset="60%" stopColor="#5f3a1f" /><stop offset="100%" stopColor="#3d2312" /></linearGradient></defs>
      <ellipse cx={0} cy={140} rx={210} ry={26} fill="rgba(0,0,0,0.4)" />
      {n > 0 && Array.from({length: n}).map((_, i) => (
        <rect key={i} x={-130 + i * 52} y={-150 - lleno * 70 - (i % 2) * 18} width={92} height={140} rx={6} fill={i % 2 ? c2 : c1} stroke="rgba(0,0,0,0.4)" strokeWidth={3} transform={`rotate(${(i - 2) * 5} ${-84 + i * 52} -20)`} />
      ))}
      <rect x={-190} y={-120} width={380} height={250} rx={30} fill="url(#cueroW)" stroke="#2c180a" strokeWidth={5} />
      {abre > 0.03 && <rect x={-170} y={-110} width={340} height={100 + 130 * abre} rx={14} fill="#241206" opacity={0.9} />}
      <g transform={`translate(0 ${abre * 175}) scale(1 ${1 - abre * 0.55})`}>
        <rect x={-190} y={-40} width={380} height={170} rx={26} fill="url(#cueroW)" stroke="#2c180a" strokeWidth={5} />
        <rect x={-170} y={-22} width={340} height={134} rx={16} fill="none" stroke="#c9a074" strokeWidth={3} strokeDasharray="12 9" opacity={0.85} />
        <rect x={120} y={10} width={70} height={64} rx={14} fill={GOLD} stroke="#2c180a" strokeWidth={4} />
      </g>
      <path d="M -190 -60 Q 0 -30 190 -60 L 190 -90 Q 0 -120 -190 -90 Z" fill="rgba(255,255,255,0.10)" />
    </g>
  );
};

const Corte: React.FC<{t: number; antes: React.ReactNode; despues: React.ReactNode}> = ({t, antes, despues}) => {
  const {s} = useS();
  return <AbsoluteFill>{s < t ? antes : despues}</AbsoluteFill>;
};

// ---------- tiempos (todo atado a palabras del guion) ----------
const TRESC = en('trescientos'), MILL = en('millones'), PERDIO = en('perdio'), CASI = en('casi');
const NAVIDAD = en('navidad'), MIL = en('mil'), VIRG = en('virginia'), JACK = en('jack'), PREMIOS = en('premios'), LOTERIA = en('loteria'), EPOCA = en('epoca');
const Y1 = en('y', 1), NOVATO = en('novato'), YA = en('ya'), EMPRESA = en('empresa'), CONSTR = en('construccion');
const PROMETIO = en('prometio'), TODOS = en('todos'), REGALO = en('regalo'), ABRIO = en('abrio'), FUNDACION = en('fundacion'), AYUDO = en('ayudo'), IGLESIAS = en('iglesias');
const PERO = en('pero'), LLAMO = en('llamo'), EQUIV = en('equivocada'), ROBOS = en('robos'), DEMANDAS = en('demandas'), PEDIDOS = en('pedidos'), LE = en('le', 1), ROBARON = en('robaron'), CIENTOS = en('cientos'), DOLARES = en('dolares'), CARRO = en('carro');
const SU4 = en('su', 4), FAMILIA = en('familia'), TRAGEDIAS = en('tragedias'), ANOS = en('anos'), ESPOSA = en('esposa'), OJALA = en('ojala'), ROTO1 = en('roto', 1), BOLETO1 = en('boleto', 1);
const EL2 = en('el', 2), PREMIO = en('premio'), CAMBIO = en('cambio'), HIZO = en('hizo'), VISIBLE = en('visible'), PLAN = en('plan'), LLAMA = en('llama'), PROBLEMAS = en('problemas', 1), RESUELVE = en('resuelve');
const DALE = en('dale'), LIKE = en('like'), COMENTA = en('comenta'), BOLETO2 = en('boleto', 2), ROTO2 = en('roto', 2), ENVIASELO = en('enviaselo'), LOTERIA2 = en('loteria', 2);

// el boleto se arruga escena por escena
const ARR = (s: number) => interpolate(s, [0, EMPRESA, FUNDACION, ROBOS, ROBARON, SU4, ESPOSA, ROTO1], [0, 0.06, 0.22, 0.4, 0.55, 0.7, 0.85, 1], clamp);

// ---------- piezas dibujadas ----------
const Boleto: React.FC<{x: number; y: number; k?: number; r?: number; arr?: number; caer?: number; rip?: number}> = ({x, y, k = 1, r = 0, arr = 0, caer = 0, rip = 0}) => {
  const NUM = ['7', '14', '23', '31', '42', '9'];
  const zig: string[] = [];
  for (let i = 0; i <= 10; i++) zig.push(`${i % 2 ? 24 : -24},${-340 + i * 68}`);
  const Cuerpo = () => (
    <g>
      <rect x={-200} y={-318} width={420} height={660} rx={26} fill="rgba(0,0,0,0.4)" />
      <rect x={-210} y={-330} width={420} height={660} rx={26} fill="url(#bolG)" stroke="#7a5208" strokeWidth={6} />
      <rect x={-210} y={-330} width={420} height={120} rx={26} fill="#c0392b" />
      <rect x={-210} y={-260} width={420} height={50} fill="#c0392b" />
      <text y={-238} textAnchor="middle" fontFamily={FONT} fontWeight={800} fontSize={64} fill="#fff">LOTERÍA</text>
      {NUM.map((n, i) => {
        const f = cl(caer * 1.4 - i * 0.1);
        const cx = -110 + (i % 3) * 110, cy = -100 + Math.floor(i / 3) * 140;
        return (
          <g key={i} transform={`translate(${cx} ${cy + f * f * 1100}) rotate(${f * (i % 2 ? 260 : -210)})`} opacity={1 - f * 0.5}>
            <circle r={46} fill="#fffaf0" stroke="#7a5208" strokeWidth={5} />
            <text y={14} textAnchor="middle" fontFamily={FONT} fontWeight={800} fontSize={44} fill="#8a1c12">{n}</text>
          </g>
        );
      })}
      <line x1={-190} y1={226} x2={190} y2={226} stroke="#7a5208" strokeWidth={4} strokeDasharray="14 10" />
      <text y={296} textAnchor="middle" fontFamily={FONT} fontWeight={800} fontSize={46} fill="#7a5208">$$$ $$$ $$$</text>
      <rect x={-210} y={-330} width={420} height={660} rx={26} fill="#5b3a14" opacity={arr * 0.42} />
      {Array.from({length: Math.round(arr * 11)}).map((_, i) => {
        const x1 = (h(i + 1) - 0.5) * 380, y1 = (h(i + 5) - 0.5) * 600, dx = (h(i + 9) - 0.5) * 340, dy = (h(i + 13) - 0.5) * 340;
        return (
          <g key={i}>
            <path d={`M ${x1} ${y1} l ${dx} ${dy}`} stroke="rgba(40,20,0,0.5)" strokeWidth={6} fill="none" strokeLinecap="round" />
            <path d={`M ${x1 + 5} ${y1 + 5} l ${dx} ${dy}`} stroke="rgba(255,240,190,0.5)" strokeWidth={3} fill="none" strokeLinecap="round" />
          </g>
        );
      })}
      <path d="M -170 -300 Q -60 -330 40 -300" stroke="rgba(255,255,255,0.55)" strokeWidth={9} fill="none" strokeLinecap="round" opacity={1 - arr * 0.7} />
    </g>
  );
  return (
    <g transform={`translate(${x} ${y}) rotate(${r}) scale(${k * (1 - arr * 0.1)} ${k * (1 - arr * 0.07)})`}>
      <defs>
        <linearGradient id="bolG" x1="0" y1="0" x2="1" y2="1"><stop offset="0%" stopColor="#ffe08a" /><stop offset="50%" stopColor="#ffc83d" /><stop offset="100%" stopColor="#e0971a" /></linearGradient>
        <clipPath id="bolL"><polygon points={`-400,-340 ${zig.join(' ')} -400,340`} /></clipPath>
        <clipPath id="bolR"><polygon points={`${zig.join(' ')} 400,340 400,-340`} /></clipPath>
      </defs>
      {rip <= 0.001 ? <Cuerpo /> : (
        <>
          <g transform={`translate(${-rip * 120} ${rip * 70}) rotate(${-rip * 22})`}><g clipPath="url(#bolL)"><Cuerpo /></g></g>
          <g transform={`translate(${rip * 120} ${rip * 130}) rotate(${rip * 26})`}><g clipPath="url(#bolR)"><Cuerpo /></g></g>
        </>
      )}
    </g>
  );
};

const Luces: React.FC<{y: number}> = ({y}) => {
  const {s} = useS();
  const cols = [RED, GREEN, GOLD, BLUE];
  return (
    <svg width={1080} height={1920} style={{position: 'absolute', inset: 0}}>
      <path d={`M -20 ${y} Q 270 ${y + 110} 540 ${y} Q 810 ${y + 110} 1100 ${y}`} stroke="#0b1a10" strokeWidth={6} fill="none" />
      {Array.from({length: 11}).map((_, i) => {
        const t = i / 10;
        const bx = -20 + t * 1120, by = y + (i % 2 ? 56 : 28) * Math.sin(t * Math.PI) + 18;
        const c = cols[i % 4], a = 0.55 + 0.45 * Math.sin(s * 3 + i * 1.3);
        return (
          <g key={i} opacity={a}>
            <circle cx={bx} cy={by} r={52} fill={c} opacity={0.18} />
            <circle cx={bx} cy={by} r={15} fill={c} stroke="rgba(0,0,0,0.4)" strokeWidth={2} />
            <circle cx={bx - 4} cy={by - 5} r={5} fill="#fff" opacity={0.8} />
          </g>
        );
      })}
    </svg>
  );
};

// ================= SITIO A: el boleto grande, dorado (E1 y E8) =================
const SA_CAM = [P(0, 540, 980, 1.12), P(MILL, 540, 1000, 1.3), P(PERDIO, 540, 1020, 1.5), P(CASI + 0.3, 540, 1100, 1.3), P(NAVIDAD - 0.4, 540, 1000, 1.15)];
const SH_CAM = [P(DALE - 0.2, 540, 960, 1.25), P(ROTO2, 540, 960, 1.15), P(ENVIASELO, 540, 980, 1.08), P(DUR, 540, 970, 1.0)];
const SitioA: React.FC<{fin?: boolean}> = ({fin = false}) => {
  const {s, spr} = useS();
  const caer = fin ? 0 : ro(s, PERDIO, PERDIO + 1.5);
  const sh = fin ? 0 : golpe(s, PERDIO, 28, 8) * 16;
  const hover = fin ? wp(s, [{t: DALE - 0.2, x: 540, y: -260}, {t: LIKE, x: 560, y: 150}, {t: COMENTA, x: 520, y: 430}, {t: BOLETO2, x: 540, y: 210}, {t: ROTO2, x: 560, y: 330}, {t: ENVIASELO, x: 540, y: 120}, {t: DUR, x: 540, y: 90}]) : {x: 0, y: 0};
  const tw = fin ? golpe(s, ROTO2, 20, 6) * 10 : 0;
  return (
    <AbsoluteFill>
      <Camara paradas={fin ? SH_CAM : SA_CAM}>
        <Textura tipo="fibra" base="radial-gradient(circle at 50% 45%, #6a1426 0%, #330a14 68%, #14040a 100%)" linea="rgba(255,200,120,0.14)" luz="rgba(255,190,120,0.12)" semilla={151} />
        <Luces y={470} />
        <Brillo x={540} y={960} r={fin ? 380 : 540} color={fin ? 'rgba(255,200,61,0.22)' : 'rgba(255,200,61,0.5)'} />
        <svg width={1080} height={1920} style={{position: 'absolute', inset: 0}}>
          <Boleto x={540} y={960 + sh} k={1.28} r={Math.sin(s * 1.5) * 3} caer={caer} />
          {fin && <Mano x={hover.x + 300} y={hover.y + 420} r={180 + tw} k={0.8} dedo={false} piel={1} manga="#6b4a3a" largo={600} />}
        </svg>
        {!fin && <Contador desde={0} hasta={315} t0={TRESC} t1={MILL + 0.3} x={540} y={1560} prefijo="$" sufijo=" M" color={GOLD} size={110} flecha={false} />}
        {!fin && <Ondas x={540} y={960} t0={PERDIO} color={RED} radio={520} />}
        {fin && <Ondas x={540} y={960} t0={ROTO2} color={GOLD} radio={300} />}
        <Polvo n={18} color="rgba(255,225,170,0.5)" />
      </Camara>
    </AbsoluteFill>
  );
};

// ================= SITIO B: el cheque gigante y la Navidad (E2) =================
const SB_CAM = [P(NAVIDAD - 0.1, 540, 1500, 1.35), P(MIL, 540, 1350, 1.3), P(VIRG, 540, 1150, 1.2), P(JACK, 540, 1000, 1.1), P(PREMIOS, 540, 960, 1.1), P(EPOCA + 0.6, 540, 940, 1.05)];
const SitioB: React.FC = () => {
  const {s, spr} = useS();
  const up = eo(ro(s, VIRG - 0.2, JACK + 0.6));
  const cy = 1480 - up * 560;
  const wob = Math.sin(s * 2.1) * 2;
  return (
    <AbsoluteFill>
      <Camara paradas={SB_CAM}>
        <Textura tipo="fibra" base="radial-gradient(circle at 50% 40%, #1f3a78 0%, #0d1a3c 70%, #050b1c 100%)" linea="rgba(160,190,255,0.14)" luz="rgba(160,190,255,0.10)" semilla={152} />
        <svg width={1080} height={1920} style={{position: 'absolute', inset: 0}}>
          {Array.from({length: 14}).map((_, i) => {
            const c = [RED, GREEN, GOLD, BLUE][i % 4];
            return <circle key={i} cx={h(i * 3 + 300) * 1080} cy={420 + h(i * 5 + 301) * 1100} r={50 + h(i) * 60} fill={c} opacity={0.10 + 0.07 * Math.sin(s * 1.6 + i)} />;
          })}
          {/* el hombre mayor: sombrero de vaquero asomando tras el cheque */}
          <g transform={`translate(540 ${cy - 330 + wob})`}>
            <ellipse cx={0} cy={-10} rx={150} ry={34} fill="#5a3418" stroke="#2c180a" strokeWidth={5} />
            <path d="M -92 -20 Q -88 -170 0 -178 Q 88 -170 92 -20 Z" fill="#7a4a24" stroke="#2c180a" strokeWidth={5} />
            <rect x={-92} y={-62} width={184} height={26} fill="#2c180a" />
            <path d="M -90 10 Q 0 120 90 10 Q 60 -4 0 0 Q -60 -4 -90 10 Z" fill="#e3b88e" stroke="#c99a6e" strokeWidth={4} />
            <path d="M -38 54 Q 0 40 38 54 Q 20 72 0 66 Q -20 72 -38 54 Z" fill="#cfcfcf" />
            <path d="M -16 28 L -6 42 L 10 42" stroke="#c99a6e" strokeWidth={5} fill="none" strokeLinecap="round" />
          </g>
          {/* el cheque de carton */}
          <g transform={`translate(540 ${cy + wob}) rotate(${Math.sin(s * 1.3) * 1.6})`}>
            <rect x={-420} y={-210} width={840} height={440} rx={14} fill="rgba(0,0,0,0.4)" transform="translate(10 14)" />
            <rect x={-420} y={-220} width={840} height={440} rx={14} fill="#f4ead2" stroke="#b79a52" strokeWidth={8} />
            <rect x={-390} y={-190} width={780} height={380} rx={8} fill="none" stroke="#c0392b" strokeWidth={5} strokeDasharray="22 12" />
            <text x={0} y={-90} textAnchor="middle" fontFamily={FONT} fontWeight={800} fontSize={78} fill="#7a5208">PREMIO MAYOR</text>
            <text x={0} y={60} textAnchor="middle" fontFamily={FONT} fontWeight={800} fontSize={140} fill="#c0392b">$315 M</text>
